static record load(FILE*f){record r;uint32_t n=rd32(f);r.ok=rd32(f);r.wn=rd32(f);r.count=rd32(f);r.terminal=rd32(f);CHECK(rd32(f)==0);r.seq=rd64(f);CHECK(n<256&&r.wn<=70000&&r.count<=33);r.name=(char*)alloc((size_t)n+1);CHECK(fread(r.name,1,n,f)==n);r.name[n]=0;r.entries=(mfd_entry_view_v1*)alloc((size_t)r.count*sizeof(*r.entries));for(uint32_t i=0;i<r.count;i++){mfd_entry_view_v1*e=r.entries+i;memset(e,0,sizeof(*e));CHECK(fread(e->entry_id,1,32,f)==32);e->name_length=rd32(f);e->encoding=rd32(f);e->kind=rd32(f);e->has_logical_length=rd32(f);e->logical_length=rd64(f);CHECK(e->name_length<=20000);uint8_t*name=(uint8_t*)alloc(e->name_length);CHECK(fread(name,1,e->name_length,f)==e->name_length);e->name=name;}r.wire=(uint8_t*)alloc(r.wn);CHECK(fread(r.wire,1,r.wn,f)==r.wn);return r;}
static void drop(record*r){for(uint32_t i=0;i<r->count;i++)free((void*)r->entries[i].name);free(r->entries);free(r->name);free(r->wire);}
