static record named(const char*input,const char*name){FILE*f=fopen(input,"rb");CHECK(f);CHECK(fseek(f,8,SEEK_SET)==0);uint32_t n=rd32(f);for(uint32_t i=0;i<n;i++){record r=load(f);if(strcmp(r.name,name)==0){fclose(f);return r;}drop(&r);}CHECK(0);fclose(f);record r;memset(&r,0,sizeof(r));return r;}
